<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Sorting Visualizer</title>
<style>
  body{background:#121212;color:#eee;font-family:system-ui,Segoe UI,Roboto,sans-serif;margin:0;padding:20px}
  #controls{margin-bottom:12px}
  button{background:#222;color:#eee;border:1px solid #444;padding:8px 14px;margin-right:8px;border-radius:6px;cursor:pointer}
  button:hover{background:#2a2a2a}
  #bars{display:flex;align-items:flex-end;gap:3px;height:420px;width:100%;overflow:hidden}
  .bar{flex:1;background:#4caf50;min-width:4px;border-radius:2px 2px 0 0;transition:height .15s}
  .bar:nth-child(odd){background:#66bb6a}
</style>
</head>
<body>
<div id="controls">
  <button id="sort">Sort</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
</div>
<div id="bars"></div>
<script>
const BAR_COUNT = 60;
let arr = [];
let initialArray = [];

function shuffleArray(a){
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
}
function generateRandom(){
  const a=[];
  for(let i=0;i<BAR_COUNT;i++) a.push(Math.floor(Math.random()*100)+5);
  return a;
}
function render(){
  const container=document.getElementById('bars');
  container.innerHTML='';
  const max=Math.max(...arr,1);
  arr.forEach(v=>{
    const d=document.createElement('div');
    d.className='bar';
    d.style.height=(v/max*100)+'%';
    container.appendChild(d);
  });
}
function isSorted(a){
  for(let i=1;i<a.length;i++) if(a[i-1]>a[i]) return false;
  return true;
}
let sortState={i:0,j:0,done:false};
function resetSortState(){sortState={i:0,j:0,done:false};}
function sortStep(){
  if(sortState.done) return true;
  if(arr.length<=1){sortState.done=true;return true;}
  if(sortState.i>=arr.length-1){sortState.done=true;return true;}
  if(sortState.j<arr.length-sortState.i-1){
    if(arr[sortState.j]>arr[sortState.j+1]){
      [arr[sortState.j],arr[sortState.j+1]]=[arr[sortState.j+1],arr[sortState.j]];
    }
    sortState.j++;
    return false;
  }else{
    sortState.i++;
    sortState.j=0;
    if(sortState.i>=arr.length-1){sortState.done=true;return true;}
    return false;
  }
}

initialArray=generateRandom();
arr=[...initialArray];
render();

document.getElementById('sort').onclick=()=>{
  resetSortState();
  const id=setInterval(()=>{
    const done=sortStep();
    render();
    if(done){clearInterval(id);}
  },20);
};
document.getElementById('shuffle').onclick=()=>{
  arr=generateRandom();
  resetSortState();
  render();
};
document.getElementById('reset').onclick=()=>{
  arr=[...initialArray];
  resetSortState();
  render();
};

window.viz={
  array:()=>arr.slice(),
  setArray:(a)=>{arr=a.slice();resetSortState();render();},
  sortStep,
  sorted:()=>isSorted(arr)
};
</script>
</body>
</html>
